const props=defineProps<{staff:any}>(),emit=defineEmits(['unauthorized','section-change']);
const section=ref('appointments'),clinic=ref(''),date=ref(''),today=ref(''),now=ref(''),clinics=ref<any[]>([]),appointments=ref<any[]>([]),visits=ref<any[]>([]),schedules=ref<any[]>([]),catalogue=ref<any[]>([]);
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),mode=ref(''),form=ref<any>({}),target=ref<any>(null),returnArrival=ref(false),arrivalDraft=ref<any>(null);
const revisit=ref<RevisitHint|null>(null),revisitQuery=ref('');
const canAdoptRevisit=computed(()=>initialized.value&&!loading.value&&!busy.value&&!pending.value&&!cacheBlocked.value&&!mode.value&&props.staff.functions?.includes('appointment.manage')&&props.staff.functions?.includes('patient.identity'));
function adoptRevisit(value:unknown){if(!canAdoptRevisit.value)return;try{const hint=revisitHint(value);if(hint.clinicId!==clinic.value.toLowerCase())throw Error('协作信息不属于当前诊所。');const cached=sessionStorage.getItem('adc.frontdeskPending:'+props.staff.accountId);if(cached&&cached!=='null')throw Error('请先核对原提交缓存，再采用协作信息。');void open('book',undefined,true);revisit.value=hint;revisitQuery.value=hint.contact.trim().length>=2?hint.contact:hint.patientName.trim().length>=2?hint.patientName:'';form.value.intention='人工复诊协作参考：'+hint.followupId+'；具体复诊目的待与患者核实。';}catch(e){error.value=explain(e);}}
watch(()=>[props.staff.accountId,props.staff.employeeId,clinic.value],()=>{if(revisit.value){revisit.value=null;revisitQuery.value='';mode.value='';form.value={};target.value=null;}},{flush:'sync'});
const initialized=ref(false),checkingSchedule=ref(false),cacheBlocked=ref(false);
const queueDoctors=ref<any[]>([]),queueDoctorClinic=ref('');
const queueSearch=ref(''),queueDoctor=ref(''),queueState=ref('all'),queueLimit=ref(50),queueNext=ref<string|null>(null),queueTotal=ref(0),queueStats=ref<any>(null),queueAsOf=ref(''),appliedQueue=ref('');
const appointmentView=ref<'list'|'board'>('list'),linkedVisit=ref(''),queueProgress=ref(false);
let slotReadGeneration=0;
let readGeneration=0,readController:AbortController|null=null;const contactControllers=new Map<string,AbortController>();
const queueKey=()=>JSON.stringify([clinic.value,date.value,queueSearch.value.trim(),queueDoctor.value,queueState.value,queueLimit.value]);const queueDirty=computed(()=>!!appliedQueue.value&&queueKey()!==appliedQueue.value);

const visitSearch=ref(''),visitDoctor=ref(''),visitState=ref('all'),visitLimit=ref(50),visitNext=ref<string|null>(null),visitTotal=ref(0),visitStats=ref<any>(null),visitAsOf=ref(''),appliedVisits=ref(''),visitDoctors=ref<any[]>([]),visitDoctorClinic=ref('');
const visitKey=()=>JSON.stringify([clinic.value,date.value,visitSearch.value.trim(),visitDoctor.value,visitState.value,visitLimit.value,linkedVisit.value]);
