const scheduleDoctor=ref(''),scheduleInternal=ref('all'),schedulePublic=ref('all'),scheduleLimit=ref(50),scheduleNext=ref<string|null>(null),scheduleTotal=ref(0),scheduleStats=ref<any>(null),scheduleAsOf=ref(''),appliedSchedules=ref(''),scheduleDoctors=ref<any[]>([]),scheduleDoctorClinic=ref('');
const scheduleKey=()=>JSON.stringify([clinic.value,date.value,scheduleDoctor.value,scheduleInternal.value,schedulePublic.value,scheduleLimit.value]);
