watch(writeScope,()=>{if(internalWriteChange)return;writeEpoch++;writeJob++;if(activeWrite){stopReads();loading.value=false;activeWrite=false;busy.value=false;mode.value='';form.value={};target.value=null;pending.value=null;notice.value='';recover();}},{flush:'sync'});
let readEpoch=0,initGeneration=0,personnelGeneration=0,previewGeneration=0;
const identityScope=()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,[...(props.staff.functions||[])].sort()]);
function readTicket(){const epoch=readEpoch,scope=writeScope(),identity=identityScope();return()=>writeAlive&&epoch===readEpoch&&scope===writeScope()&&identity===identityScope();}
watch(()=>JSON.stringify([identityScope(),clinic.value,date.value,section.value]),(value,old)=>{if(internalWriteChange)return;linkedVisit.value='';readEpoch++;slotReadGeneration++;personnelGeneration++;previewGeneration++;stopReads();loading.value=false;if(checkingSchedule.value)busy.value=false;checkingSchedule.value=false;clearQueue();clearVisits();clearSchedules();groups.value=[];personnel.value={doctors:[],nurses:[]};preview.value=null;previewBody.value='';mode.value='';target.value=null;form.value={};arrivalDraft.value=null;returnArrival.value=false;revisit.value=null;revisitQuery.value='';error.value='';notice.value='';queueDoctors.value=[];visitDoctors.value=[];scheduleDoctors.value=[];if(old&&JSON.parse(value)[0]!==JSON.parse(old)[0]){initGeneration++;initialized.value=false;clinics.value=[];catalogue.value=[];pending.value=null;recover();}},{flush:'sync'});
const status:Record<string,string>={active:'已确认',cancelled:'已取消',arrived:'已到院',no_show:'未到结案'};
const pad=(n:number)=>String(n).padStart(2,'0');
const local=(s?:string)=>new Date((s?Date.parse(s):Date.now())+8*3600000).toISOString().slice(0,19);
const instant=(s:string)=>new Date(s+'+08:00').toISOString();
const clock=(s:string)=>s?new Date(s).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}):'—';
const full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}):'—';
class ApiError extends Error{constructor(public status:number,message:string){super(message);}}
async function api(path:string,body?:any,signal?:AbortSignal){const abort=requestAbort(12000,signal);try{const r=await fetch('/api/v1'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:abort.signal});const b=await r.json().catch(()=>({}));if(!r.ok)throw new ApiError(r.status,b.message||'请求失败，请重试。');return b;}finally{abort.dispose();}}
function explain(e:unknown){return e instanceof Error?e.message:'操作失败。';}
const clinicItems=computed(()=>catalogue.value.filter(i=>i.clinicId===clinic.value));
const doctorOptions=computed(()=>Array.from(new Map(clinicItems.value.map(i=>[i.doctorId,i])).values()));
const queueDoctorChoices=computed(()=>[...new Map([...doctorOptions.value.map(d=>({id:d.doctorId,name:d.doctorName})),...(queueDoctorClinic.value===clinic.value?queueDoctors.value:[])].map(d=>[d.id,d])).values()]);
const visitDoctorChoices=computed(()=>[...new Map([...doctorOptions.value.map(d=>({id:d.doctorId,name:d.doctorName})),...(visitDoctorClinic.value===clinic.value?visitDoctors.value:[])].map(d=>[d.id,d])).values()]);
const scheduleDoctorChoices=computed(()=>[...new Map([...doctorOptions.value.map(d=>({id:d.doctorId,name:d.doctorName})),...(scheduleDoctorClinic.value===clinic.value?scheduleDoctors.value:[])].map(d=>[d.id,d])).values()]);
const serviceOptions=computed(()=>clinicItems.value.filter(i=>i.doctorId===form.value.doctorId));
const slotOptions=computed(()=>groups.value.flatMap(g=>g.slots.map((s:any)=>({...s,group:g,key:g.scheduleId+'|'+s.startsAt}))));
const selectedSlot=computed(()=>slotOptions.value.find(s=>s.key===form.value.slotKey));

const titles:Record<string,string>={book:'前台代办预约',contact:'记录真实联系',cancel:'核实后取消预约',no_show:'人工核实未到',arrival:'登记实际到院',progress:'登记实际就诊进展',patient:'建立最小患者档案',schedule:'维护医生排班'};
const knownReplies=new Map<string,{original:string;confirmed:string;saved:any}>();
function pendingKey(){return 'adc.frontdeskPending:'+props.staff.accountId;}
function recover(){try{const key=pendingKey(),raw=sessionStorage.getItem(key),known=knownReplies.get(key);cacheBlocked.value=false;if(known&&(raw===known.original||raw===known.confirmed)){pending.value=known.saved;return;}pending.value=parseFrontdeskPending(raw,props.staff);}catch(e){const known=knownReplies.get(pendingKey());if(known?.saved.accountId===props.staff.accountId&&known.saved.employeeId===props.staff.employeeId){pending.value=known.saved;cacheBlocked.value=false;error.value='已收到明确回复；本机缓存暂不可读，请稍后只清理。';}else{pending.value=null;cacheBlocked.value=true;error.value=explain(e);}}}
function clearConfirmed(){if(busy.value||!clearOnly(pending.value))return;const key=pendingKey(),saved=pending.value,known=knownReplies.get(key);if(saved.accountId!==props.staff.accountId||saved.employeeId!==props.staff.employeeId){error.value='请用原账号和员工身份清理。';return;}try{const raw=sessionStorage.getItem(key),expected=known?.confirmed||JSON.stringify(saved);if(raw!==null&&raw!==expected&&raw!==known?.original){recover();error.value='缓存已变化，未清除其他请求。';return;}if(raw!==null)sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('缓存仍未清除');knownReplies.delete(key);pending.value=null;error.value='';notice.value='已清理本机提交缓存；未再次办理业务。';}catch{error.value='已收到明确回复；本机缓存尚未清除，请重试清理，不要重新办理。';}}
function resumePending(){if(clearOnly(pending.value))clearConfirmed();else if(pending.value&&!frontdeskRecoveryTarget(pending.value))void send(pending.value.path,pending.value.body,pending.value.label);}
function bookingRecovered(p:any){if(p!==pending.value)return;try{const raw=sessionStorage.getItem(pendingKey());if(!raw||JSON.stringify(JSON.parse(raw))!==JSON.stringify(p))throw Error('缓存已变化，请保留当前请求。');if(rememberSuccess(p,pendingKey(),raw)){mode.value='';target.value=null;form.value={};groups.value=[];notice.value='已只读核实原前台操作已保存；未重复办理。';}}catch(e){error.value=explain(e);}}
function retryBooking(p:any){if(p===pending.value)void send(p.path,p.body,p.label);}
function rememberSuccess(saved:any,key:string,raw:string,phase:'confirmed'|'rejected'='confirmed'){const confirmed={...saved,phase,accountId:props.staff.accountId,employeeId:props.staff.employeeId},text=JSON.stringify(confirmed);knownReplies.set(key,{original:raw,confirmed:text,saved:confirmed});pending.value=confirmed;try{if(sessionStorage.getItem(key)!==raw){recover();error.value='原提交已收到成功回复，缓存已变化；未清除其他请求。';return false;}try{sessionStorage.setItem(key,text);}catch{}try{sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('仍有缓存');knownReplies.delete(key);pending.value=null;}catch{error.value='已收到明确回复；本机缓存尚未清除，请重试清理，不要重新办理。';}}catch{error.value='已收到明确回复；本机缓存暂不可读，请稍后只清理。';}return true;}
function clearQueue(){appointments.value=[];queueNext.value=null;queueTotal.value=0;queueStats.value=null;queueAsOf.value='';appliedQueue.value='';}
function clearVisits(){visits.value=[];visitNext.value=null;visitTotal.value=0;visitStats.value=null;visitAsOf.value='';appliedVisits.value='';}
function clearSchedules(){schedules.value=[];scheduleNext.value=null;scheduleTotal.value=0;scheduleStats.value=null;scheduleAsOf.value='';appliedSchedules.value='';}
function stopReads(){readGeneration++;readController?.abort();readController=null;for(const c of contactControllers.values())c.abort();contactControllers.clear();for(const r of appointments.value)r.contactsBusy=false;}
function readDenied(status:number){readEpoch++;initGeneration++;slotReadGeneration++;personnelGeneration++;previewGeneration++;stopReads();loading.value=false;if(checkingSchedule.value)busy.value=false;checkingSchedule.value=false;initialized.value=false;catalogue.value=[];groups.value=[];personnel.value={doctors:[],nurses:[]};preview.value=null;clearQueue();clearVisits();clearSchedules();mode.value='';target.value=null;form.value={};if(status===401)emit('unauthorized');}
async function loadList(more=false){
 if(!initialized.value)return initialize();if(!clinic.value)return;
 const selectedSection=section.value,dirty=selectedSection==='visits'?visitsDirty.value:selectedSection==='schedules'?schedulesDirty.value:queueDirty.value,next=selectedSection==='visits'?visitNext.value:selectedSection==='schedules'?scheduleNext.value:queueNext.value;
 if(more&&(loading.value||dirty||!next)){if(dirty)error.value='筛选条件已改变，请先查询。';return;}
 stopReads();const gen=readGeneration,key=listKey();
 if(queueDoctorClinic.value!==clinic.value)queueDoctors.value=[];
 if(visitDoctorClinic.value!==clinic.value)visitDoctors.value=[];
 if(scheduleDoctorClinic.value!==clinic.value)scheduleDoctors.value=[];
 readController=new AbortController();const own=readController;loading.value=true;error.value='';
 if(!more){clearQueue();clearVisits();clearSchedules();}
 try{
  if(selectedSection==='appointments'||selectedSection==='visits'){
   const isVisit=selectedSection==='visits';
   const q=new URLSearchParams({date:date.value,clinicId:clinic.value,q:(isVisit?visitSearch.value:queueSearch.value).trim(),state:isVisit?visitState.value:queueState.value,limit:String(isVisit?visitLimit.value:queueLimit.value)});
   const doctor=isVisit?visitDoctor.value:queueDoctor.value;if(doctor)q.set('doctorId',doctor);if(more&&next)q.set('cursor',next);
   if(isVisit&&linkedVisit.value)q.set('visitId',linkedVisit.value);
   if(!isVisit&&(more?queueProgress.value:appointmentView.value==='board'))q.set('progress','1');
   const r=await api('/frontdesk/'+selectedSection+'?'+q,undefined,own.signal);
   if(gen!==readGeneration||selectedSection!==section.value||key!==listKey())return;
   if(isVisit){
    visits.value=more?[...visits.value,...r.items]:r.items;visitAsOf.value=r.asOf;visitNext.value=r.nextCursor;visitTotal.value=r.total;visitStats.value=r.summary;appliedVisits.value=key;
    visitDoctorClinic.value=clinic.value;visitDoctors.value=[...new Map([...visitDoctors.value,...r.doctors].map((d:any)=>[d.id,d])).values()];
   }else{
    queueProgress.value=q.has('progress');appointments.value=more?[...appointments.value,...r.items]:r.items;now.value=r.now;queueAsOf.value=r.asOf;queueNext.value=r.nextCursor;queueTotal.value=r.total;queueStats.value=r.summary;appliedQueue.value=key;
    queueDoctorClinic.value=clinic.value;queueDoctors.value=[...new Map([...queueDoctors.value,...r.doctors].map((d:any)=>[d.id,d])).values()];
   }
  }else{
   const q=new URLSearchParams({date:date.value,clinicId:clinic.value,internal:scheduleInternal.value,publicState:schedulePublic.value,limit:String(scheduleLimit.value)});
   if(scheduleDoctor.value)q.set('doctorId',scheduleDoctor.value);if(more&&next)q.set('cursor',next);
   const r=await api('/frontdesk/schedules?'+q,undefined,own.signal);
   if(gen!==readGeneration||selectedSection!==section.value||key!==listKey())return;
   schedules.value=more?[...schedules.value,...r.items]:r.items;scheduleAsOf.value=r.asOf;scheduleNext.value=r.nextCursor;scheduleTotal.value=r.total;scheduleStats.value=r.summary;appliedSchedules.value=key;
   scheduleDoctorClinic.value=clinic.value;scheduleDoctors.value=[...new Map([...scheduleDoctors.value,...r.doctors].map((d:any)=>[d.id,d])).values()];
  }
 }catch(e){
  if(gen!==readGeneration)return;
  if(e instanceof ApiError&&(e.status===401||e.status===403))readDenied(e.status);
  else if(!more||e instanceof ApiError&&e.status===409){if(selectedSection==='visits')clearVisits();else if(selectedSection==='schedules')clearSchedules();else clearQueue();}
  error.value=explain(e);
 }finally{if(gen===readGeneration){loading.value=false;readController=null;}}
}
async function refresh(){return loadList(false);}
async function showBoard() {
 if (loading.value || busy.value || mode.value || appointmentView.value === 'board') return;
 appointmentView.value = 'board';
 await refresh();
}
async function showAppointmentList(id?: string) {
 appointmentView.value = 'list';
 // The board and list use the same page and order. Keep the loaded page when opening a card.
 if (id) {
  await nextTick();
  const row=document.getElementById('frontdesk-appointment-'+id);
  row?.focus();
 }
}
async function showLinkedVisit(appointment: BoardAppointment) {
 if (!props.staff.functions?.includes('visit.read') || !appointment.visitId || !appointment.visitState ||
     !appointment.arrivedAt || busy.value || pending.value || cacheBlocked.value) return;
 const arrived=Date.parse(appointment.arrivedAt);
 if (!Number.isFinite(arrived)) return;
 date.value=local(appointment.arrivedAt).slice(0,10);
 section.value='visits';
 visitSearch.value='';visitState.value='all';visitDoctor.value='';
 linkedVisit.value=appointment.visitId;
 emit('section-change',section.value);
 await refresh();
}
function clearFilters(){queueSearch.value='';queueDoctor.value='';queueState.value='all';refresh();}
function clearVisitFilters(){visitSearch.value='';visitDoctor.value='';visitState.value='all';refresh();}
function clearScheduleFilters(){scheduleDoctor.value='';scheduleInternal.value='all';schedulePublic.value='all';refresh();}
async function moreContacts(a:any){if(a.contactsBusy||!a.contactsCursor)return;const gen=readGeneration,own=new AbortController();contactControllers.set(a.id,own);a.contactsBusy=true;error.value='';try{const r=await api('/frontdesk/appointments/'+a.id+'/contacts?limit=20&cursor='+encodeURIComponent(a.contactsCursor),undefined,own.signal);if(gen!==readGeneration||!appointments.value.includes(a))return;a.contacts=[...a.contacts,...r.items];a.contactsCursor=r.nextCursor;a.contactsTotal=r.total;}catch(e){if(gen!==readGeneration)return;if(e instanceof ApiError&&(e.status===401||e.status===403))readDenied(e.status);else if(e instanceof ApiError&&e.status===409){a.contacts=[];a.contactsCursor=null;a.contactsTotal=0;}error.value=explain(e);}finally{if(gen===readGeneration){a.contactsBusy=false;contactControllers.delete(a.id);}}}
function setSection(s:string){linkedVisit.value='';section.value=s;emit('section-change',s);refresh();}
function shiftDay(days:number){if(!date.value)return;date.value=new Date(Date.parse(date.value+'T00:00:00Z')+days*86400000).toISOString().slice(0,10);refresh();}
function choosePerson(type:string,p:any){form.value.patientId=type==='patient'?p.id:(p.patientId||'');form.value.bookingSubjectId=type==='subject'?p.id:'';form.value.name=p.name;form.value.contact=p.phone;form.value.patientLabel=p.name;}
function identityDenied(status:number){mode.value='';target.value=null;form.value={};if(status===401)emit('unauthorized');else error.value='当前已无本诊所身份核实权限，请重新读取工作范围。';}
async function loadPersonnel(at?:string){const d=at?at.slice(0,10):date.value,current=readTicket(),gen=++personnelGeneration,editing=form.value,kind=mode.value;try{const r=await api(`/frontdesk/personnel?clinicId=${clinic.value}&date=${d}`);if(current()&&gen===personnelGeneration&&editing===form.value&&kind===mode.value)personnel.value=r;}catch(e){if(current()&&gen===personnelGeneration&&editing===form.value&&kind===mode.value){personnel.value={doctors:[],nurses:[]};if(e instanceof ApiError&&(e.status===401||e.status===403))readDenied(e.status);error.value=explain(e);}}}
async function loadSlots(){
 const ticket=readTicket(),editing=form.value,gen=++slotReadGeneration,services=serviceOptions.value;if(!services.some(s=>s.serviceVersionId===form.value.serviceVersionId))form.value.serviceVersionId=services[0]?.serviceVersionId||'';
 groups.value=[];form.value.slotKey='';if(!form.value.bookingDate||!form.value.doctorId||!form.value.serviceVersionId)return;
 const key=JSON.stringify([clinic.value,form.value.bookingDate,form.value.doctorId,form.value.serviceVersionId]);
 const current=()=>ticket()&&editing===form.value&&gen===slotReadGeneration&&mode.value==='book'&&key===JSON.stringify([clinic.value,form.value.bookingDate,form.value.doctorId,form.value.serviceVersionId]);
 try{const r=await api(`/availability?date=${form.value.bookingDate}&clinicId=${clinic.value}&doctorId=${form.value.doctorId}&serviceVersionId=${form.value.serviceVersionId}`);if(current())groups.value=r.groups;}catch(e){if(current()){if(e instanceof ApiError&&(e.status===401||e.status===403))readDenied(e.status);error.value=explain(e);}}
}
async function open(m:string,a?:any,fromRevisit=false){if(pending.value){error.value='请先核实原提交，再办理下一笔。';return;}revisit.value=null;revisitQuery.value='';mode.value=m;target.value=a||null;error.value='';preview.value=null;returnArrival.value=false;
 form.value={name:a?.name||'',contact:a?.contact||'',intention:a?.intention||'',identityBasis:'',confirmedWithPatient:false,contactedAt:local(),contactNote:'',note:'',nextAction:'',outcome:'unreachable',estimatedArrivalAt:'',basis:'',reason:'',reviewedPriorNoShow:false,checkedRegistration:false,verifiedNoShow:false,identityConfirmed:false,nurseIds:[],arrivedAt:local(),occurredAt:local(),field:'started_at',isBackfill:false,coordination:'',patientId:a?.patientId||'',patientLabel:a?.patientId?a.name:'',bookingSubjectId:a?.bookingSubjectId||'',bookingDate:date.value,doctorId:a?.doctorId||doctorOptions.value[0]?.doctorId,serviceVersionId:'',slotKey:'',birthDate:'',sourceNote:'',startsAt:date.value+'T09:00:00',endsAt:date.value+'T12:00:00',canReceive:true,publicStatus:'not_open',capacityLimit:1,confirmImpact:false};
 if(m==='book'){if(fromRevisit){form.value.doctorId='';form.value.bookingDate='';groups.value=[];}else await loadSlots();}
 if(m==='arrival')await loadPersonnel(form.value.arrivedAt);
 if(m==='progress'){form.value.field='started_at';form.value.occurredAt=local(a.startedAt||undefined);}
 if(m==='schedule'){if(a)Object.assign(form.value,{doctorId:a.doctor_id,startsAt:local(a.starts_at),endsAt:local(a.ends_at),canReceive:a.can_receive,publicStatus:a.public_status,capacityLimit:a.capacity_limit,reason:''});await loadPersonnel();}
}
function openCreateFromArrival(){arrivalDraft.value={...form.value,nurseIds:[...form.value.nurseIds]};returnArrival.value=true;mode.value='patient';form.value={name:target.value?.name||'',contact:target.value?.contact||'',birthDate:'',sourceNote:'',identityBasis:''};}
function close(){if(busy.value||pending.value)return;mode.value='';target.value=null;returnArrival.value=false;}
async function send(path:string,body:any,label:string){if(busy.value||!writeAlive||cacheBlocked.value)return;if(clearOnly(pending.value)){clearConfirmed();return;}if(pending.value&&(pending.value.path!==path||pending.value.body.requestId!==body.requestId)){error.value='请先核实原提交。';return;}
 const retrying=!!pending.value;const saved=retrying?JSON.parse(JSON.stringify(pending.value)):makeFrontdeskPending(path,body,label,props.staff),key='adc.frontdeskPending:'+props.staff.accountId,canonical=JSON.stringify(saved),epoch=writeEpoch,job=++writeJob,scope=writeScope(),editing=form.value;
 const active=()=>writeAlive&&epoch===writeEpoch&&job===writeJob&&scope===writeScope()&&editing===form.value;let sent=false,raw=canonical;
 busy.value=true;activeWrite=true;error.value='';notice.value='';try{
 const prior=sessionStorage.getItem(key);if(prior&&prior!=='null'&&prior!==raw){if(retrying&&JSON.stringify(parseFrontdeskPending(prior,props.staff))===canonical)raw=prior;else{recover();error.value='原提交缓存与本次请求不一致，请先核实原提交。';return;}}
 sessionStorage.setItem(key,raw);sent=true;const r=await api(path,saved.body);if(!active())return;
 if(!rememberSuccess(saved,key,raw))return;
 if(path==='/frontdesk/appointments'&&Number.isFinite(Date.parse(r.startsAt))){internalWriteChange=true;try{date.value=new Date(r.startsAt).toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});}finally{internalWriteChange=false;}}
 notice.value=r.repeated?'已核实原提交，未重复办理。':r.existing?'该预约已登记，返回原实际就诊。':label;
 if(mode.value==='patient'&&returnArrival.value){form.value={...arrivalDraft.value,patientId:r.id,patientLabel:r.name};mode.value='arrival';returnArrival.value=false;}else{mode.value='';target.value=null;}
 try{await refresh();}catch{}return r;
 }catch(e){if(!active())return;error.value=explain(e);if(!sent)return;
 try{if(sessionStorage.getItem(key)!==raw){recover();error.value='缓存已变化，请先核实当前原提交。';return;}}catch{pending.value=saved;error.value='结果暂不能确认，原提交缓存暂不可读；请保持原账号核对，不要另办。';return;}
 if(!(e instanceof ApiError)||e.status>=500||e.status===401){pending.value=saved;error.value='结果暂不能确认，请保持原账号并核实原提交，不要重新办理。';if(e instanceof ApiError&&e.status===401)emit('unauthorized');}else if(retrying){pending.value=saved;error.value='原结果仍待核实，请保留原请求：'+explain(e);}else{rememberSuccess(saved,key,raw,'rejected');}
 }finally{if(job===writeJob){busy.value=false;activeWrite=false;}}
}
function scheduleBody(){const f=form.value;return {id:target.value?.schedule_id||null,version:target.value?Number(target.value.row_version):null,clinicId:clinic.value,doctorId:f.doctorId,startsAt:instant(f.startsAt),endsAt:instant(f.endsAt),canReceive:f.canReceive,publicStatus:f.publicStatus,capacityLimit:Number(f.capacityLimit),reason:f.reason};}
async function previewSchedule(){if(busy.value||pending.value)return;const current=readTicket(),editing=form.value,gen=++previewGeneration;checkingSchedule.value=true;busy.value=true;error.value='';try{const body=scheduleBody(),signature=JSON.stringify(body),result=await api('/frontdesk/schedules/preview',body);if(!current()||editing!==form.value||gen!==previewGeneration||mode.value!=='schedule'||signature!==JSON.stringify(scheduleBody()))return;preview.value=result;previewBody.value=signature;form.value.confirmImpact=false;}catch(e){if(current()&&editing===form.value&&gen===previewGeneration){if(e instanceof ApiError&&(e.status===401||e.status===403))readDenied(e.status);error.value=explain(e);preview.value=null;}}finally{if(current()&&gen===previewGeneration){checkingSchedule.value=false;busy.value=false;}}}
async function save(){if(busy.value||pending.value||cacheBlocked.value)return;const f=form.value,a=target.value,requestId=crypto.randomUUID();try{
 if(mode.value==='patient')return send('/frontdesk/patients',{requestId,clinicId:clinic.value,name:f.name,phone:f.contact,birthDate:f.birthDate||null,sourceNote:f.sourceNote||null,identityBasis:f.identityBasis},'患者档案已建立，过敏状态保持尚未了解。');
 if(mode.value==='book'){if(revisit.value&&!f.patientId){error.value='请先检索并选择本诊所已有患者，核实身份后再代约。';return;}const s=selectedSlot.value;if(!s){error.value='请选择完整可约时段。';return;}const body={requestId,scheduleId:s.group.scheduleId,serviceVersionId:s.group.serviceVersionId,ruleVersionId:s.group.ruleVersionId,startsAt:s.startsAt,name:f.name,contact:f.contact,intention:f.intention,identityBasis:f.identityBasis,patientId:f.patientId||null,bookingSubjectId:f.bookingSubjectId||null,confirmedWithPatient:f.confirmedWithPatient,...(a?{version:a.version,contactedAt:instant(f.contactedAt),contactNote:f.contactNote}:{})};return send(a?`/frontdesk/appointments/${a.id}/reschedule`:'/frontdesk/appointments',body,a?'已按商定安排改约。':'前台代约成功，已直接确认。');}
 if(mode.value==='contact')return send(`/frontdesk/appointments/${a.id}/contact`,{requestId,version:a.version,contactedAt:instant(f.contactedAt),outcome:f.outcome,note:f.note,nextAction:f.nextAction||null,estimatedArrivalAt:f.estimatedArrivalAt?instant(f.estimatedArrivalAt):null},'联系已保存；预约状态未自动改变。');
 if(mode.value==='cancel')return send(`/frontdesk/appointments/${a.id}/cancel`,{requestId,version:a.version,reason:f.reason,confirmedWithPatient:f.confirmedWithPatient,contactedAt:instant(f.contactedAt),contactNote:f.contactNote},'已核实取消并释放本次占用。');
 if(mode.value==='no_show')return send(`/frontdesk/appointments/${a.id}/no-show`,{requestId,version:a.version,basis:f.basis,checkedRegistration:f.checkedRegistration,verifiedNoShow:f.verifiedNoShow},'已保存人工核实未到结案及依据。');
 if(mode.value==='arrival')return send('/frontdesk/visits',{requestId,clinicId:clinic.value,appointmentId:a?.id||null,appointmentVersion:a?.version||null,patientId:f.patientId,doctorId:f.doctorId,nurseIds:f.nurseIds,arrivedAt:instant(f.arrivedAt),basis:f.basis,identityConfirmed:f.identityConfirmed,identityBasis:f.identityBasis,coordination:f.coordination,isBackfill:f.isBackfill,reason:f.reason||null,reviewedPriorNoShow:f.reviewedPriorNoShow===true},'实际到院已登记；临床内容仍由医生记录。');
 if(mode.value==='progress')return send(`/frontdesk/visits/${a.id}/progress`,{requestId,version:a.version,field:f.field,occurredAt:instant(f.occurredAt),basis:f.basis,reason:f.reason||null,isBackfill:f.isBackfill,reviewedPriorNoShow:f.reviewedPriorNoShow===true},'真实进展已保存，原值和来源保留。');
 if(mode.value==='schedule'){const body=scheduleBody();if(!preview.value||previewBody.value!==JSON.stringify(body)){error.value='请先预览当前内容及预约影响。';return;}return send('/frontdesk/schedules',{...body,requestId,impactToken:preview.value.impactToken,confirmImpact:f.confirmImpact},'排班已保存；受影响预约须另行联系。');}
}catch(e){error.value=explain(e);}}
function contactNext(s:string){try{const v=JSON.parse(s||'{}');return [v.actionNote,v.estimatedArrivalAt?'预计到达 '+full(v.estimatedArrivalAt):''].filter(Boolean).join(' · ');}catch{return s;}}
async function initialize(){if(busy.value||mode.value)return;const gen=++initGeneration,identity=identityScope();let epoch=readEpoch;const current=()=>writeAlive&&gen===initGeneration&&identity===identityScope()&&epoch===readEpoch;loading.value=true;initialized.value=false;error.value='';recover();emit('section-change',section.value);try{const b=await api('/frontdesk/bootstrap');if(!current())return;clinics.value=b.clinics;today.value=b.today;date.value=b.today;now.value=b.now;clinic.value=b.clinics[0]?.id||'';epoch=readEpoch;loading.value=true;const items=await api('/catalogue');if(!current())return;catalogue.value=items.items;initialized.value=true;await refresh();}catch(e){if(current()){initialized.value=false;if(e instanceof ApiError&&(e.status===401||e.status===403))readDenied(e.status);error.value=explain(e);}}finally{if(current())loading.value=false;}}
onMounted(initialize);onBeforeUnmount(()=>{writeAlive=false;readEpoch++;initGeneration++;writeEpoch++;writeJob++;activeWrite=false;stopReads();clearQueue();clearVisits();clearSchedules();});
defineExpose({refresh,setSection});
</script>

<template><div class="frontdesk">
 <div v-if="cacheBlocked" class="b-alert warning">原提交缓存异常，已保留。请核查原请求后重新读取，期间不能新办理。<button type="button" class="b-button small" @click="recover">重新读取原提交缓存</button></div><div v-if="error" class="b-alert error" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="notice" class="b-alert success" role="status"><Check :size="17"/>{{notice}}<button @click="notice=''">关闭</button></div>
 <FrontdeskBookingRecovery v-if="frontdeskRecoveryTarget(pending)&&!clearOnly(pending)" :pending="pending" :clinic-id="clinic" :account-id="staff.accountId" :employee-id="staff.employeeId" @completed="bookingRecovered" @retry="retryBooking" @unauthorized="emit('unauthorized')"/><div v-if="pending&&(!frontdeskRecoveryTarget(pending)||clearOnly(pending))" class="b-alert warning">{{clearOnly(pending)?(pending.phase==='rejected'?'本次请求已明确拒绝，仅待清理本机缓存。':'业务已收到成功回复，仅待清理本机缓存。'):'有一笔结果待核实，请保留原账号。'}}<button class="b-button small" :disabled="busy||(!!frontdeskRecoveryTarget(pending)&&!clearOnly(pending))" @click="resumePending">{{clearOnly(pending)?'仅清理本机缓存':!!frontdeskRecoveryTarget(pending)?'请在上方只读核实原前台操作':'核实原提交'}}</button></div>
 <div class="f-tabs"><button :class="{active:section==='appointments'}" @click="setSection('appointments')"><CalendarDays :size="17"/>预约与联系</button><button :class="{active:section==='visits'}" @click="setSection('visits')"><UserCheck :size="17"/>实际接诊</button><button :class="{active:section==='schedules'}" @click="setSection('schedules')"><Clock3 :size="17"/>医生排班</button></div>
 <div class="b-card f-toolbar"><label>办理诊所<select v-model="clinic" @change="refresh"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{section==='visits'?'实际到院日期':section==='schedules'?'排班覆盖日期':'日期'}}<input type="date" v-model="date" @change="refresh"/></label><button v-if="section==='appointments' && appointmentView==='board'" class="f-text" @click="shiftDay(-1)">前一天</button><button class="f-text" @click="date=today;refresh()">今天</button><button class="f-text" @click="shiftDay(1)">后一天</button><button class="b-button outline small" :disabled="loading" @click="refresh"><RefreshCw :size="15"/>刷新</button></div>
 <div v-if="!initialized" class="b-card b-empty">{{loading?'正在连接工作台…':'尚未取得当前办理范围，请重新连接。'}}<button class="b-button outline small" :disabled="loading" @click="initialize">重新连接</button></div>
 <div v-else-if="!clinics.length" class="b-card b-empty">当前账号没有诊所办理范围，请联系有权人员配置。</div>
 <template v-else>
 <RevisitImport v-if="section==='appointments'&&staff.functions?.includes('appointment.manage')&&staff.functions?.includes('patient.identity')" :key="staff.accountId+staff.employeeId" :clinic-id="clinic" :blocked="!canAdoptRevisit" @adopt="adoptRevisit"/>
 <section v-if="section==='appointments'" class="b-card f-queue-filters"><label>预约人姓名 / 电话<input v-model="queueSearch" maxlength="100" placeholder="输入预约人姓名或电话" @keydown.enter.prevent="refresh"/></label><label>医生筛选<select v-model="queueDoctor"><option value="">全部医生</option><option v-for="d in queueDoctorChoices" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>预约状态<select v-model="queueState"><option value="all">全部预约</option><option value="active">有效预约</option><option value="due">超过5分钟待联系</option><option value="arrived">已有关联实际到院</option><option value="cancelled">已取消</option><option value="no_show">未到结案</option></select></label><label>每页预约<select v-model="queueLimit"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><div class="f-queue-query"><button class="b-button small" :disabled="loading" @click="refresh"><Search :size="15"/>查询</button><button class="f-text" :disabled="loading" @click="clearFilters">清空筛选</button></div><p v-if="queueDirty" class="f-queue-dirty">筛选条件已改变，请查询后查看新结果。</p><p v-if="queueAsOf" class="f-queue-summary">已显示 {{appointments.length}} / {{queueTotal}} 份 · 读取时点 {{full(queueAsOf)}}。汇总统计覆盖姓名与医生条件下的全部预约，不随状态筛选缩小；关联实际到院可与已取消或未到结案重叠。</p></section>
 <div v-if="section==='appointments'" class="f-overview"><div><strong>{{queueStats?.active??'—'}}</strong><span>有效预约</span></div><div><strong>{{queueStats?.contactDue??'—'}}</strong><span>超过5分钟待核对联系</span></div><div><strong>{{queueStats?.arrived??'—'}}</strong><span>已登记到院</span></div><div class="f-overview-note"><AlertCircle :size="17"/>未接通不自动取消；窗口结束且核实后才记未到。</div></div>
 <section v-if="section==='appointments'" class="b-card f-list"><div class="f-list-head"><div><h2>{{appointmentView==='board'?(date===today?'今日排班':'预约排班'):'预约与联系'}}</h2><p>线上与前台使用同一安排，普通预约没有待审批步骤。</p></div><div class="f-actions"><button class="b-button outline small" type="button" :disabled="loading||busy||!!mode" v-if="appointmentView==='list'" @click="showBoard"><CalendarDays :size="16"/>排班图</button><button v-else class="b-button outline small" type="button" :disabled="loading||busy||!!mode" @click="showAppointmentList()">预约列表</button><button class="b-button outline small" :disabled="busy||!!pending||cacheBlocked" @click="open('patient')">最小建档</button><button class="b-button small" :disabled="busy||!!pending||cacheBlocked" @click="open('book')"><Plus :size="16"/>前台代约</button></div></div>
 <template v-if="appointmentView==='board'">
   <p v-if="loading && !appointments.length" class="b-empty">正在读取排班…</p>
   <p v-else-if="queueDirty || !queueAsOf" class="b-empty">请查询以读取当前日期的排班图。</p>
   <AppointmentBoard v-else :appointments="appointments" :date="date"
    :doctors="queueDoctor ? queueDoctorChoices.filter(d => d.id === queueDoctor) : queueDoctorChoices"
    :blocked="loading || busy || !!pending || cacheBlocked"
    :writable="staff.functions?.includes('visit.manage') === true"
    :can-see-visits="staff.functions?.includes('visit.read') === true"
    @arrive="open('arrival',$event)" @visit="showLinkedVisit" @list="showAppointmentList"/>
 </template>
 <div v-else class="b-table-scroll"><table><thead><tr><th>时间 / 预约人</th><th>医生与服务</th><th>状态 / 跟进</th><th>办理</th></tr></thead><tbody><template v-for="a in appointments" :key="a.id"><tr :id="'frontdesk-appointment-'+a.id" tabindex="-1"><td><b>{{bookingTimeRange(a.startsAt,a.endsAt)}}</b><strong class="f-name">{{a.name}}</strong><small>{{a.contact}} · {{a.id.slice(0,8).toUpperCase()}}</small></td><td>{{a.doctorName}}<small>{{a.serviceName}}</small></td><td><span class="b-pill" :class="a.disposition">{{status[a.disposition]}}</span><small v-if="a.contactDue" class="f-warning">待核对漏登记并联系</small><small v-if="a.visitId">已有关联实际就诊</small></td><td><div class="f-row-actions"><button :disabled="busy||!!pending||cacheBlocked" @click="open('contact',a)">联系</button><button v-if="a.disposition==='active'" :disabled="busy||!!pending||cacheBlocked" @click="open('book',a)">改约</button><button v-if="a.disposition==='active'" :disabled="busy||!!pending||cacheBlocked" @click="open('cancel',a)">取消</button><button v-if="!a.visitId" :disabled="busy||!!pending||cacheBlocked" @click="open('arrival',a)">{{a.disposition==='active'?'登记到院':'登记实际到院（需核实）'}}</button><button v-if="a.noShowAllowed" :disabled="busy||!!pending||cacheBlocked" @click="open('no_show',a)">未到核实</button></div></td></tr><tr v-if="a.contacts.length"><td colspan="4" class="f-contact-row"><details><summary>{{a.contactsTotal}} 条联系历史 · 已显示 {{a.contacts.length}}</summary><p v-for="h in a.contacts" :key="h.id">{{full(h.contactedAt)}} · {{h.note}} <span>{{contactNext(h.nextAction)}}</span></p><button v-if="a.contactsCursor" class="b-button outline small" :disabled="a.contactsBusy||loading" @click="moreContacts(a)">{{a.contactsBusy?'正在读取…':'读取更早联系'}}</button></details></td></tr></template><tr v-if="!appointments.length"><td colspan="4" class="b-empty">{{loading?'正在读取…':queueAsOf?'当前日期和筛选条件下没有预约。':'请查询以读取当前预约。'}}</td></tr></tbody></table></div><div class="f-queue-more"><button v-if="queueNext" class="b-button outline" :disabled="loading||queueDirty" @click="loadList(true)">{{loading?'正在读取…':'继续读取预约'}}</button></div></section>
 <section v-if="section==='visits'" class="b-card f-queue-filters f-visit-filters">
 <label>患者姓名<input v-model="visitSearch" maxlength="100" placeholder="输入患者姓名" @keydown.enter.prevent="refresh"/></label>
 <label>接诊医生<select v-model="visitDoctor"><option value="">全部医生</option><option v-for="d in visitDoctorChoices" :key="d.id" :value="d.id">{{d.name}}</option></select></label>
 <label>接诊进展<select v-model="visitState"><option value="all">全部接诊</option><option value="waiting">已到院待接诊</option><option value="in_progress">接诊中</option><option value="ended">本次接诊结束</option><option value="left">已离开</option></select></label>
 <label>每页接诊<select v-model="visitLimit"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label>
 <div class="f-queue-query"><button class="b-button small" :disabled="loading" @click="refresh"><Search :size="15"/>查询</button><button class="f-text" :disabled="loading" @click="clearVisitFilters">清空筛选</button></div>
 <p v-if="visitsDirty" class="f-queue-dirty">筛选条件已改变，请查询后查看新结果。</p>
 <p v-if="visitAsOf" class="f-queue-summary">已显示 {{visits.length}} / {{visitTotal}} 份 · 读取时点 {{full(visitAsOf)}}。四类统计覆盖姓名与医生条件下的全部接诊，不随进展筛选缩小。</p>
 </section>
 <div v-if="section==='visits'" class="f-overview f-visit-overview"><div><strong>{{visitStats?.waiting??'—'}}</strong><span>已到院待接诊</span></div><div><strong>{{visitStats?.inProgress??'—'}}</strong><span>接诊中</span></div><div><strong>{{visitStats?.ended??'—'}}</strong><span>本次接诊结束</span></div><div><strong>{{visitStats?.left??'—'}}</strong><span>已离开</span></div><div class="f-overview-note"><AlertCircle :size="17"/>按已登记事实归类；提前离开不代表已完成治疗。</div></div>
 <section v-if="section==='visits'" class="b-card f-list"><div class="f-list-head"><div><h2>实际接诊</h2><p v-if="linkedVisit">当前显示所选预约对应的接诊。<button class="f-text" type="button" :disabled="loading||busy||!!mode" @click="linkedVisit='';refresh()">查看当日全部接诊</button></p><p v-else>前台据实登记四个时点，病历与治疗仍由医生负责。</p></div><button class="b-button small" :disabled="busy||!!pending||cacheBlocked" @click="open('arrival')"><Plus :size="16"/>无预约到院</button></div><div class="b-table-scroll"><table><thead><tr><th>患者 / 人员</th><th>实际时间</th><th>安排 / 迟到</th><th>办理</th></tr></thead><tbody><tr v-for="v in visits" :key="v.id"><td><strong>{{v.patientName}}</strong><small>{{v.doctorName}} · {{v.nurses.map((n:any)=>n.name).join('、')}}</small></td><td><div class="f-time-facts"><span>到院 <b>{{clock(v.arrivedAt)}}</b></span><span>开始 <b>{{clock(v.startedAt)}}</b></span><span>结束 <b>{{clock(v.endedAt)}}</b></span><span>离开 <b>{{clock(v.leftAt)}}</b></span></div></td><td><span class="b-pill">{{visitLabels[v.state]}}</span><small v-if="v.appointmentId">原预约：{{status[v.originalAppointmentState]}}<template v-if="v.lateMinutes>0"> · 迟到 {{v.lateMinutes}} 分钟</template></small><small v-else>无预约实际到院</small></td><td><button class="b-button outline small" :disabled="busy||!!pending||cacheBlocked" @click="open('progress',v)">登记 / 更正进展</button></td></tr><tr v-if="!visits.length"><td colspan="4" class="b-empty">{{loading?'正在读取…':visitAsOf?'当前日期和筛选条件下没有实际接诊。':'请查询以读取实际接诊。'}}</td></tr></tbody></table></div><div class="f-queue-more"><button v-if="visitNext" class="b-button outline" :disabled="loading||visitsDirty" @click="loadList(true)">{{loading?'正在读取…':'继续读取接诊'}}</button></div></section>
 <section v-if="section==='schedules'" class="b-card f-queue-filters f-schedule-filters">
 <label>排班医生<select v-model="scheduleDoctor"><option value="">全部医生</option><option v-for="d in scheduleDoctorChoices" :key="d.id" :value="d.id">{{d.name}}</option></select></label>
 <label>内部接诊筛选<select v-model="scheduleInternal"><option value="all">全部内部安排</option><option value="available">可接诊</option><option value="unavailable">不可接诊</option></select></label>
 <label>对外开放筛选<select v-model="schedulePublic"><option value="all">全部公开安排</option><option value="open">开放预约</option><option value="paused">暂停预约</option><option value="not_open">尚未开放</option></select></label>
 <label>每页排班<select v-model="scheduleLimit"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label>
 <div class="f-queue-query"><button class="b-button small" :disabled="loading" @click="refresh"><Search :size="15"/>查询</button><button class="f-text" :disabled="loading" @click="clearScheduleFilters">清空筛选</button></div>
 <p v-if="schedulesDirty" class="f-queue-dirty">筛选条件已改变，请查询后查看新结果。</p>
 <p v-if="scheduleAsOf" class="f-queue-summary">已显示 {{schedules.length}} / {{scheduleTotal}} 份 · 读取时点 {{full(scheduleAsOf)}}。统计覆盖所选医生在该日的全部排班，不随内部或公开状态筛选缩小；跨午夜安排显示完整起止时间。</p>
 </section>
 <div v-if="section==='schedules'" class="f-overview f-schedule-overview"><div><strong>{{scheduleStats?.available??'—'}}</strong><span>内部可接诊</span><small>不可接诊 {{scheduleStats?.unavailable??'—'}} 份</small></div><div><strong>{{scheduleStats?.open??'—'}}</strong><span>对外开放</span></div><div><strong>{{scheduleStats?.paused??'—'}}</strong><span>暂停预约</span></div><div><strong>{{scheduleStats?.notOpen??'—'}}</strong><span>尚未开放</span></div><div class="f-overview-note"><AlertCircle :size="17"/>内部接诊与公开安排分别统计。患者能否预约，还须核对服务、执业、时段和剩余名额。</div></div>
 <section v-if="section==='schedules'" class="b-card f-list"><div class="f-list-head"><div><h2>医生排班</h2><p>内部可接诊与对外开放分开；修改前核对预约影响。</p></div><button class="b-button small" :disabled="busy||!!pending||cacheBlocked" @click="open('schedule')"><Plus :size="16"/>新增排班</button></div><div class="b-table-scroll"><table><thead><tr><th>医生 / 时间</th><th>内部接诊</th><th>公开安排</th><th>办理</th></tr></thead><tbody><tr v-for="s in schedules" :key="s.schedule_id"><td><strong>{{s.doctor_name}}</strong><small>{{full(s.starts_at)}} — {{full(s.ends_at)}}</small></td><td>{{s.can_receive?'可接诊':'不可接诊'}}</td><td>{{{open:'开放',paused:'暂停',not_open:'未开放'}[s.public_status]}}<small>同一瞬间容量 {{s.capacity_limit}} · 版本 {{s.row_version}}</small></td><td><button class="b-button outline small" :disabled="busy||!!pending||cacheBlocked" @click="open('schedule',s)">维护并核对影响</button></td></tr><tr v-if="!schedules.length"><td colspan="4" class="b-empty">{{loading?'正在读取…':scheduleAsOf?'该日期和筛选条件下没有排班。':'请查询以读取排班。'}}</td></tr></tbody></table></div><div class="f-queue-more"><button v-if="scheduleNext" class="b-button outline" :disabled="loading||schedulesDirty" @click="loadList(true)">{{loading?'正在读取…':'继续读取排班'}}</button></div></section>
 <div class="f-scope-note">北京时间 · 只用合成资料。本日内部示例值班用于检查实际到院，并未对患者开放预约。</div>
 </template>
 <div v-if="mode" class="b-backdrop"><form class="b-dialog f-dialog" role="dialog" aria-modal="true" :aria-label="titles[mode]" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭前台办理" :disabled="busy||!!pending||cacheBlocked" @click="close"><X :size="21"/></button><div class="b-eyebrow">FRONT DESK / {{mode.toUpperCase()}}</div><h2>{{mode==='book'&&target?'前台协商改约':titles[mode]}}</h2><div v-if="target&&mode!=='schedule'" class="f-context">{{target.name||target.patientName}} · {{target.doctorName}}<span v-if="target.startsAt"> · {{full(target.startsAt)}}</span><small v-if="target.disposition">原预约 {{status[target.disposition]}}</small></div><div v-if="error" class="b-alert error" role="alert">{{error}}</div>
 <fieldset class="f-edit-fields" :disabled="busy||!!pending||cacheBlocked"><template v-if="['book','arrival'].includes(mode)"><div class="f-identity-search"><div v-if="revisit" class="b-alert warning">人工协作线索：{{revisit.patientName}} · {{revisit.contact||'未提供电话'}} · 原医生 {{revisit.doctorName}}。任务 {{revisit.followupId}} 仅作人工参考，须核实身份与患者意愿。</div><FrontdeskIdentitySearch :clinic-id="clinic" :initial-query="revisitQuery" :allow-subjects="mode==='book'&&!revisit" @selected="({kind,person})=>choosePerson(kind,person)" @denied="identityDenied"/><p class="b-help">{{form.patientId?'已选择正式档案：'+form.patientLabel:form.bookingSubjectId?'已选择现有预约主体。':revisit?'请检索并选择本诊所已有患者；协作线索不能代替正式档案。':'未选择已有身份；代约可人工核实首诊主体，到院必须先核实正式档案。'}} 同号不自动合档。</p><button v-if="mode==='arrival'" type="button" class="f-text" @click="openCreateFromArrival">首次到院？先最小建档，再返回登记</button></div></template>
 <template v-if="mode==='patient'"><div class="b-alert warning">仅建立到院所需最小档案，过敏保持“尚未了解”；不填写即未知，不默认为无过敏。</div><div class="b-two-fields"><label>患者姓名<input v-model="form.name" required maxlength="100"/></label><label>联系电话<input v-model="form.contact" required maxlength="40"/></label><label>出生日期（可选）<input type="date" v-model="form.birthDate"/></label><label>患者提供的来源（可选）<input v-model="form.sourceNote" maxlength="500"/></label></div><label>身份核实依据<textarea v-model="form.identityBasis" required rows="2"/></label></template>
 <template v-if="mode==='book'"><div class="b-two-fields"><label>预约日期<input type="date" v-model="form.bookingDate" @change="loadSlots" required/></label><label>医生<select v-model="form.doctorId" @change="form.serviceVersionId='';loadSlots()"><option value="" disabled>请选择医生</option><option v-for="d in doctorOptions" :key="d.doctorId" :value="d.doctorId">{{d.doctorName}} · {{d.specialty}}</option></select></label></div><label>配置服务<select v-model="form.serviceVersionId" @change="loadSlots"><option v-for="s in serviceOptions" :key="s.serviceVersionId" :value="s.serviceVersionId">{{s.serviceName}} · {{s.durationMinutes}}分钟</option></select></label><label>明确商定的时段<select v-model="form.slotKey" required><option value="">请选择可预约时段</option><option v-for="s in slotOptions" :key="s.key" :value="s.key" :disabled="s.status!=='available'">{{bookingTimeRange(s.startsAt,s.endsAt)}} · {{s.status==='available'?'可预约':s.status==='full'?'已约满':'当前不可预约'}}</option></select></label><div class="b-two-fields"><label>预约人姓名<input v-model="form.name" required maxlength="100"/></label><label>联系电话<input v-model="form.contact" required maxlength="40"/></label></div><label>就诊意向<textarea v-model="form.intention" required rows="2" maxlength="500"/></label><label>身份核实依据<textarea v-model="form.identityBasis" required rows="2"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.confirmedWithPatient" required/><span>已与本人明确商定医生、服务和起止时间；不替患者接受其他安排。</span></label></template>
 <template v-if="mode==='contact'"><label>真实联系时间（北京时间）<input type="datetime-local" step="1" v-model="form.contactedAt" required/></label><label>本次结果<select v-model="form.outcome"><option value="unreachable">未接通 / 未联系上</option><option value="coming">已联系，正在赶来</option><option value="cannot_come">本人明确表示来不了</option><option value="other">其他已联系结果</option></select></label><label>真实结果说明<textarea v-model="form.note" required rows="2"/></label><div class="b-two-fields"><label>预计到达（不是实际到院，可选）<input type="datetime-local" step="1" v-model="form.estimatedArrivalAt"/></label><label>后续跟进 / 协调<input v-model="form.nextAction" maxlength="1000"/></label></div><p class="b-help">联系不上不自动取消或结案；来不了时请另行核实并明确办理取消。</p></template>
 <template v-if="mode==='cancel'||(mode==='book'&&target)"><label>真实联系时间（北京时间）<input type="datetime-local" step="1" v-model="form.contactedAt" required/></label><label>实际联系及商定结果<textarea v-model="form.contactNote" required rows="2"/></label><template v-if="mode==='cancel'"><label>取消原因<textarea v-model="form.reason" required rows="2"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.confirmedWithPatient" required/><span>已核实患者明确取消意愿。必要人工处理不受线上自助截止限制，已到院不得回滚。</span></label></template></template>
 <template v-if="mode==='no_show'"><div class="b-alert warning">仅在预约窗口结束后核实办理。没有到院记录或电话未接通本身不是充分依据。</div><label>真实核实依据<textarea v-model="form.basis" required rows="3"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.checkedRegistration" required/><span>已检查漏登记和现场实际情况。</span></label><label class="b-checkbox"><input type="checkbox" v-model="form.verifiedNoShow" required/><span>已人工核实该预约确实未到；不是只依据未接通。</span></label></template>
 <template v-if="mode==='arrival'"><label>实际到院时间（北京时间）<input type="datetime-local" step="1" v-model="form.arrivedAt" required @change="loadPersonnel(form.arrivedAt)"/></label><label>明确选择接诊医生<select v-model="form.doctorId" required><option value="">请选择</option><option v-for="d in personnel.doctors" :key="d.id" :value="d.id">{{d.name}}</option></select></label><fieldset class="f-nurses"><legend>配合护士（至少一名，可多选）</legend><label v-for="n in personnel.nurses" :key="n.id" class="b-checkbox"><input type="checkbox" v-model="form.nurseIds" :value="n.id"/><span>{{n.name}}</span></label><small v-if="!personnel.nurses.length">该日暂无明确有效的护士安排。</small></fieldset><label>到院真实核实依据<textarea v-model="form.basis" required rows="2"/></label><label>预约人与档案对应的核实依据<textarea v-model="form.identityBasis" required rows="2"/></label><label>已与医生核对并告知患者的当前安排<textarea v-model="form.coordination" required rows="2" placeholder="例如：已与医生确认，患者已知需等候；不自动插队或顺延他人。"/></label><label v-if="target" class="b-checkbox"><input type="checkbox" v-model="form.identityConfirmed" required/><span>已核实预约人与所选档案的对应。旧取消或未到结案不被静默恢复。</span></label><label class="b-checkbox"><input type="checkbox" v-model="form.isBackfill"/><span>这是据实补录（请填写原因）。</span></label><label>补录原因（适用时必填）<input v-model="form.reason" maxlength="1000"/></label></template>
 <template v-if="mode==='progress'"><div class="f-current-facts">已有事实：到院 {{full(target.arrivedAt)}} · 开始 {{full(target.startedAt)}} · 结束 {{full(target.endedAt)}} · 离开 {{full(target.leftAt)}}</div><label>本次登记 / 更正类别<select v-model="form.field" @change="form.occurredAt=local()"><option value="started_at">接诊开始（据医护反馈）</option><option value="ended_at">本次接诊结束（据医护反馈）</option><option value="left_at">实际离开（前台核实）</option><option value="arrived_at">更正实际到院（前台核实）</option></select></label><label>真实发生时间（北京时间）<input type="datetime-local" step="1" v-model="form.occurredAt" required/></label><label>真实发生依据<textarea v-model="form.basis" required rows="2"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.isBackfill"/><span>据实补录此前发生事实。</span></label><label>更正、补录或离开后补充的原因<input v-model="form.reason" maxlength="1000"/></label><p class="b-help">早退可直接登记离开；没有真实开始不能补造结束。离开后补录不重开旧就诊。</p></template>
 <template v-if="mode==='schedule'"><label>排班医生<select v-model="form.doctorId" :disabled="!!target" required><option v-if="target&&!personnel.doctors.some((d:any)=>d.id===form.doctorId)" :value="form.doctorId">{{target.doctor_name}}（原排班医生）</option><option v-for="d in personnel.doctors" :key="d.id" :value="d.id">{{d.name}}</option></select></label><div class="b-two-fields"><label>时段起点（北京时间）<input type="datetime-local" step="1" v-model="form.startsAt" required/></label><label>时段终点（北京时间）<input type="datetime-local" step="1" v-model="form.endsAt" required/></label></div><label class="b-checkbox"><input type="checkbox" v-model="form.canReceive"/><span>内部可以接诊</span></label><div class="b-two-fields"><label>对外开放状态<select v-model="form.publicStatus"><option value="not_open">尚未开放</option><option value="open">开放预约</option><option value="paused">暂停预约</option></select></label><label>同一瞬间预约容量<input type="number" min="1" step="1" v-model="form.capacityLimit" required/></label></div><label>明确安排或变更原因<textarea v-model="form.reason" required rows="2"/></label><button class="b-button outline full" type="button" :disabled="busy" @click="previewSchedule">预览并核对预约影响</button><div v-if="preview" class="f-impact"><strong>{{preview.affected.length}} 份预约需核对</strong><p v-for="a in preview.affected" :key="a.appointment_id">{{a.booked_name}} · {{full(a.scheduled_at)}}—{{clock(a.scheduled_end_at)}}</p><label class="b-checkbox"><input type="checkbox" v-model="form.confirmImpact"/><span>已核对上述影响；保存排班后另行联系处理，不自动取消或改约。</span></label></div></template>
 <label v-if="(mode==='arrival'&&target?.disposition==='no_show')||(mode==='progress'&&target?.originalAppointmentState==='no_show')" class="b-checkbox"><input type="checkbox" v-model="form.reviewedPriorNoShow"/><span>若真实到院发生在原未到窗口结束之前，已核实漏登记及原结论，并在原因中说明更正。原未到历史仍保留。</span></label></fieldset><button v-if="pending" class="b-button full" type="button" :disabled="busy||(!!frontdeskRecoveryTarget(pending)&&!clearOnly(pending))" @click="resumePending">{{clearOnly(pending)?'仅清理本机缓存':!!frontdeskRecoveryTarget(pending)?'请在上方只读核实原前台操作':'核实原提交'}}</button><button v-else class="b-button full" :disabled="busy||(mode==='arrival'&&!form.patientId)||(mode==='schedule'&&(!preview||(preview.affected.length>0&&!form.confirmImpact)))">{{busy?(checkingSchedule?'正在核对…':'正在保存…'):mode==='schedule'?'确认保存排班':mode==='arrival'?'确认真实到院':mode==='patient'?'确认建档':'确认保存'}}</button><p class="b-help">当前仅本机合成数据。保存时再次检查权限、版本及业务规则。</p>
 </form></div>
</div></template>

<style scoped>.f-edit-fields{border:0;padding:0;margin:0;min-width:0}</style>
